import sys, json, importlib.util, subprocess
OUT=sys.argv[1]
def load(name, path):
    s=importlib.util.spec_from_file_location(name, path); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
syn = load("comm_syntax", f"{OUT}/comm.py").comm_syntax_spec
assert len(syn)==1 and len(syn[0])==2
opts, pos = syn[0]
print("syntax ok: %d option nodes, %d positional nodes" % (len(opts), len(pos)))
tbl = json.load(open(f"{OUT}/annotation/comm.json"))
flags = {s for e in tbl["flag"] for s in ([e] if isinstance(e,str) else e)}
options = {s for e in tbl["option"] for s in e[:-1]}
# cross-check syntax vs json
syn_flags = {s for n in opts if type(n).__name__=="Flag" for s in [n.flag]+n.alias}
syn_opts = {s for n in opts if type(n).__name__!="Flag" for s in [n.flag]+n.alias}
assert syn_flags==flags, (syn_flags, flags)
assert syn_opts==options, (syn_opts, options)
print("json matches syntax:", sorted(flags), sorted(options))
# compare every spelling against the real binary (long options also with =)
import os
open("/tmp/commtest/a","w").write("a\nb\n"); open("/tmp/commtest/b","w").write("b\nc\n")
for f in sorted(flags - {"--help","--version"}):
    r=subprocess.run(["comm",f,"/tmp/commtest/a","/tmp/commtest/b"],capture_output=True,text=True)
    assert r.returncode==0, (f, r.stderr)
for o in sorted(options):
    for argv in (["comm",o+"=X"],["comm",o,"X"]):
        r=subprocess.run(argv+["/tmp/commtest/a","/tmp/commtest/b"],capture_output=True,text=True)
        assert r.returncode==0 and "X" in r.stdout, (argv, r.stderr)
# check the binary accepts no other single-letter flags we missed
for ch in "abcdefghijklmnopqrstuvwxyABCDEFGHIJKLMNOPQRSTUVWXYZ0456789":
    r=subprocess.run(["comm","-"+ch,"/tmp/commtest/a","/tmp/commtest/b"],capture_output=True,text=True)
    assert r.returncode!=0, "binary accepts undocumented -%s"%ch
print("all listed flags/options accepted by binary; no other short flags exist")
# emulate PaSh parser & run IO generator
IO = load("io", f"{OUT}/annotation/InputOutputInfoGeneratorComm.py").InputOutputInfoGeneratorComm
PAR = load("par", f"{OUT}/annotation/ParallelizabilityInfoGeneratorComm.py").ParallelizabilityInfoGeneratorComm
def parse(words):
    fl=[]; ops=[]; i=0
    while i<len(words):
        w=words[i]
        if w in flags: fl.append(w)
        elif w in options: fl.append(w); i+=1
        elif w.split("=")[0] in options and "=" in w: fl.append(w.split("=")[0])
        elif w.startswith("-") and len(w)>2 and not w.startswith("--") and all("-"+c in flags for c in w[1:]): fl += ["-"+c for c in w[1:]]
        else: ops=words[i:]; break
        i+=1
    return fl, ops
for inv in (["-12","f1","f2"], ["--output-delimiter=,","f1","-"], ["--total","-z","-","f2"], ["-3","--nocheck-order","f1","f2"]):
    fl,ops=parse(inv); g=IO(fl,ops); g.generate_info(); p=PAR(fl,ops); p.generate_info()
    print(inv, "->", fl, ops, g.log, "parallelizers:", p.parallelizers)
for inv in (["-1","f1"], [], ["f1","f2","f3"]):
    fl,ops=parse(inv)
    try: IO(fl,ops).generate_info(); print("UNEXPECTED success", inv)
    except Exception as e: print(inv, "-> raises:", e)
EOF
